// Compara las agendas de Google con la tabla `agents` y decide que cambia.
// No escribe nada: solo produce el plan. Quien escribe es "A escribir" -> "Escribir".

// Agendas que existen en Google pero NO son personas: la cuenta general y el
// calendario tecnico de sincronizacion con Kommo.
const EXCLUIR = new Set([
  'consultingsimarroproperties@gmail.com',
  '5171f451aef56f9446414a412b0b83ad9f84c8fac5ef543f900e1dbb701232d1@group.calendar.google.com'
]);

// Mismo criterio de normalizacion que parseAgent en Sync_catalogo_idealista.
const norm = (s) => (s || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Solo uno de los nodos de modo se ejecuta, segun por donde haya entrado.
// Si no se puede leer ninguno, se asume simulacion: nunca escribir por defecto.
const dry = (() => {
  for (const n of ['Modo simulacion', 'Modo aplicar', 'Modo real']) {
    try { const v = $(n).first().json; if (typeof v.dry === 'boolean') return v.dry; } catch (e) { /* rama no ejecutada */ }
  }
  return true;
})();

// Google devuelve un unico item con `items`; Supabase devuelve un item por fila.
const gRaw = ($('Leer agendas').first().json.items) || [];
const tabla = $('Leer agentes').all().map(i => i.json).filter(a => a && a.calendar_id);
const props = $('Leer catalogo').all().map(i => i.json).filter(p => p && p.agent);

const google = gRaw
  .filter(c => !EXCLUIR.has(c.id) && ['owner', 'writer'].includes(c.accessRole))
  .map(c => ({ calendar_id: c.id, display_name: c.summary || '', agent_key: norm(c.summary) }))
  .filter(c => c.agent_key);

const porCal = new Map(tabla.map(a => [a.calendar_id, a]));
const enGoogle = new Set(google.map(c => c.calendar_id));

// La clave es el NOMBRE DE PILA, porque asi es como resuelve la RPC: la fila `carlos`
// casa con "carlos gonzales llanos" escrito en Idealista, faltas incluidas. Una clave
// larga ("carlos gonzalez") no casaria con ese texto.
const primera = (s) => norm(s).split(' ')[0] || '';
const clavesUsadas = new Set(tabla.map(a => a.agent_key));
const altas = [];
const colisiones = [];
for (const c of google) {
  if (porCal.has(c.calendar_id)) continue;
  const key = primera(c.display_name);
  if (!key) continue;
  // Dos personas con el mismo nombre de pila no se pueden distinguir por lo que se
  // escribe en Idealista: eso lo decide una persona, no el automatismo.
  if (clavesUsadas.has(key)) { colisiones.push({ display_name: c.display_name, calendar_id: c.calendar_id, key }); continue; }
  clavesUsadas.add(key);
  altas.push({ agent_key: key, display_name: c.display_name, calendar_id: c.calendar_id, active: true });
}

const bajas = tabla
  .filter(a => a.active && !enGoogle.has(a.calendar_id))
  .map(a => ({ agent_key: a.agent_key, display_name: a.display_name, calendar_id: a.calendar_id, active: false }));

const reactivadas = tabla
  .filter(a => !a.active && enGoogle.has(a.calendar_id))
  .map(a => ({ agent_key: a.agent_key, display_name: a.display_name, calendar_id: a.calendar_id, active: true }));

// Cuantas viviendas del catalogo lleva cada agente, para saber que arrastra una baja.
const tok = (s) => norm(s).split(' ').filter(Boolean);
const claves = [...new Set([...tabla.map(a => a.agent_key), ...google.map(c => c.agent_key)])].filter(Boolean);
const casa = (raw) => {
  const rt = new Set(tok(raw));
  if (!rt.size) return null;
  for (const k of claves) {
    const kt = tok(k);
    if (kt.length && kt.every(t => rt.has(t))) return k;
  }
  return null;
};

const porClave = {};
const sinCasar = {};
for (const p of props) {
  const k = casa(p.agent);
  if (k) porClave[k] = (porClave[k] || 0) + 1;
  else sinCasar[norm(p.agent)] = (sinCasar[norm(p.agent)] || 0) + 1;
}

// `agente:` escrito en Idealista que no corresponde a ninguna agenda ni fila:
// hoy esas visitas caen al calendario general sin avisar a nadie.
const huerfanos = Object.entries(sinCasar)
  .map(([agente, viviendas]) => ({ agente, viviendas }))
  .sort((a, b) => b.viviendas - a.viviendas);

for (const b of bajas) b.viviendas = porClave[b.agent_key] || 0;

// Fail-closed: si Google contesta con poco, o si la tabla llega vacia, o si se irian
// de baja varios a la vez, no se toca nada. Un permiso caducado o una lectura fallida
// no pueden dar de baja a la plantilla ni duplicarla.
const motivos = [];
if (google.length < 3) motivos.push('Google ha devuelto ' + google.length + ' agendas de personas (minimo 3)');
if (!tabla.length) motivos.push('la tabla de agentes ha llegado vacia');
if (bajas.length > 2) motivos.push('se irian de baja ' + bajas.length + ' agentes a la vez (maximo 2)');
if (altas.length > 3) motivos.push('se darian de alta ' + altas.length + ' agentes a la vez (maximo 3)');
const seguro = motivos.length === 0;

const cambios = altas.length + bajas.length + reactivadas.length;

return [{ json: {
  dry, seguro, motivos,
  aplicar: seguro && !dry && cambios > 0,
  altas, bajas, reactivadas, huerfanos, colisiones,
  resumen: {
    agendas_google: google.length, filas_tabla: tabla.length,
    altas: altas.length, bajas: bajas.length, reactivadas: reactivadas.length,
    huerfanos: huerfanos.length, colisiones: colisiones.length, viviendas_catalogo: props.length
  }
} }];

// Traduce el plan en peticiones sueltas a Supabase: una por agente, para que un
// fallo en una no arrastre a las demas.
// Siempre emite al menos un item (un GET inofensivo): un nodo sin items de entrada
// no se ejecuta en n8n y cortaria la cadena hasta el aviso.
const SB = 'http://simarro-pre0225supabase-f93ff3-185-47-13-169.traefik.me/rest/v1/agents';
const p = $input.first().json;
const ops = [];

if (p.aplicar) {
  for (const a of p.altas) {
    ops.push({ que: 'alta', detalle: a.display_name, method: 'POST', url: SB, body: [a] });
  }
  for (const c of [...p.bajas, ...p.reactivadas]) {
    ops.push({
      que: c.active ? 'reactivado' : 'baja', detalle: c.display_name, method: 'PATCH',
      url: SB + '?calendar_id=eq.' + encodeURIComponent(c.calendar_id),
      body: { active: c.active }
    });
  }
}

if (!ops.length) {
  ops.push({ que: 'ping', detalle: p.dry ? 'simulacion' : 'sin cambios',
             method: 'GET', url: SB + '?select=agent_key&limit=1', body: null });
}
return ops.map(json => ({ json }));

// Construye el aviso. Solo se envia si hay algo que contar.
const p = $('Plan').first().json;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

const ops = $('A escribir').all().map(i => i.json).filter(o => o.que !== 'ping');
const res = $('Escribir').all().map(i => i.json);
const fallos = [];
ops.forEach((o, i) => {
  const r = res[i];
  if (r && r.error) fallos.push(o.que + ' ' + o.detalle + ': ' + esc(r.error.description || r.error.message || 'error'));
});

const cambios = p.altas.length + p.bajas.length + p.reactivadas.length;
const colis = p.colisiones || [];
const enviar = cambios > 0 || !p.seguro || p.huerfanos.length > 0 || fallos.length > 0 || colis.length > 0;

let asunto;
if (!p.seguro) asunto = 'Agentes: revision detenida por seguridad';
else if (fallos.length) asunto = 'Agentes: ' + fallos.length + ' cambios han fallado';
