else if (cambios) asunto = 'Agentes: ' + p.altas.length + ' altas, ' + p.bajas.length + ' bajas';
else asunto = 'Agentes: ' + p.huerfanos.length + ' viviendas con un agente que no existe';

const b = [];
b.push('<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1a1a2e;max-width:640px">');
b.push('<h2 style="font-size:17px;margin:0 0 4px">Revision diaria de agentes</h2>');
b.push('<p style="color:#6b7390;margin:0 0 16px">' + p.resumen.agendas_google + ' agendas en Google &middot; '
  + p.resumen.filas_tabla + ' en la tabla &middot; ' + p.resumen.viviendas_catalogo + ' viviendas en el catalogo</p>');

if (!p.seguro) {
  b.push('<p style="background:#fff1d6;border-left:3px solid #8a5a0b;padding:10px 12px;margin:0 0 12px">'
    + '<b>No se ha tocado nada.</b><br>' + p.motivos.map(esc).join('<br>') + '</p>');
} else if (p.dry && cambios) {
  b.push('<p style="background:#e1ecff;border-left:3px solid #003dff;padding:10px 12px;margin:0 0 12px">'
    + '<b>Simulacion.</b> Esto es lo que se haria; no se ha escrito nada.</p>');
}
if (fallos.length) {
  b.push('<p style="background:#fff1d6;border-left:3px solid #8a5a0b;padding:10px 12px;margin:0 0 12px">'
    + '<b>Cambios que han fallado</b><br>' + fallos.join('<br>') + '</p>');
}

const lista = (titulo, filas, pinta) => {
  if (!filas.length) return;
  b.push('<h3 style="font-size:14px;margin:18px 0 6px">' + titulo + '</h3><ul style="margin:0;padding-left:18px">');
  for (const f of filas) b.push('<li style="margin-bottom:4px">' + pinta(f) + '</li>');
  b.push('</ul>');
};

