lista('Bajas', p.bajas, x => '<b>' + esc(x.display_name) + '</b> &mdash; su agenda ya no esta compartida'
  + (x.viviendas ? '. <span style="color:#8a5a0b">Lleva ' + x.viviendas
      + ' viviendas en el catalogo: hay que reasignarlas o sus visitas iran al calendario general.</span>' : ''));
