b.push('</div>');

// Version corta para Slack (mrkdwn). El detalle largo va en el email.
const t = [];
t.push(!p.seguro ? ':warning: *Agentes: revision detenida por seguridad*'
     : fallos.length ? ':warning: *Agentes: cambios fallidos*'
     : p.dry && cambios ? ':mag: *Agentes (simulacion)*'
     : cambios ? ':white_check_mark: *Agentes actualizados*'
     : ':warning: *Agentes: viviendas con agente desconocido*');
t.push('_' + p.resumen.agendas_google + ' agendas en Google · ' + p.resumen.filas_tabla
     + ' en la tabla · ' + p.resumen.viviendas_catalogo + ' viviendas_');
if (!p.seguro) t.push('No se ha tocado nada: ' + p.motivos.join('; '));
if (fallos.length) t.push('*Han fallado:* ' + fallos.join(' · '));
for (const a of p.altas) t.push('• Alta: *' + a.display_name + '* — en Idealista basta con poner `agente: '
  + a.agent_key + '` y la visita ira a su agenda');
for (const x of p.bajas) t.push('• Baja: *' + x.display_name + '* — su agenda ya no esta compartida'
  + (x.viviendas ? ' :rotating_light: lleva ' + x.viviendas + ' viviendas, hay que reasignarlas' : ''));
for (const x of p.reactivadas) t.push('• Vuelve: *' + x.display_name + '*');
for (const c of colis) t.push('• :hand: *' + c.display_name + '* no se ha dado de alta: ya hay un agente *'
  + c.key + '*. Hay que decidirlo a mano.');
for (const h of p.huerfanos) t.push('• *' + h.agente + '* aparece en ' + h.viviendas
  + ' viviendas de Idealista y no tiene agenda: sus visitas caen al calendario general');

return enviar ? [{ json: { asunto, html: b.join(''), texto: t.join('\n') } }] : [];

